cd /tmp && awk 'NR>=10235' exec.log | grep -nP "frame standstill|state machine →|New event '(start|_begin|_pause|_end|_resume)|Paused trajectory|Terminal|Received response|Starting state monitor|Detaching|Operation completed" | sed -E 's/^([0-9]+):[0-9-]+ [0-9:]+ \[DEBUG\] [a-z_.]+: /\1 /' | awk '
/frame standstill/ {n++; printf "F%03d %s\n", n, $0; next}
{print "     " $0}' | head -140 | cut -c1-200

cd /tmp && awk 'NR>=10235' exec.log | grep -P "frame standstill|state machine →|New event '(start|_begin|_pause_after|_end)|Paused trajectory|Operation completed" | sed -E 's/[0-9-]+ [0-9:]+ \[DEBUG\] [a-z_.]+: //' | awk '
/frame standstill/ {n++; if (n>=28 && n<=44) printf "F%03d %s\n", n, $0; next}
{ if (n>=27 && n<=44) print "     " $0}' | cut -c1-170; echo "=== op completed / first Ended+standstill ==="; awk 'NR>=10235' exec.log | grep -nP "Operation completed|frame standstill=True execute=TrajectoryEnded" | head -2 | cut -c1-220; awk 'NR>=10235' exec.log | grep -P "frame standstill" | awk '{n++} /standstill=True execute=TrajectoryEnded/ && !d {d=1; print "first Ended+standstill: F"n}'
